def countOneRectangles(matrix):
    cols = len(matrix[0])
    h = [0] * cols
    total = 0
    for row in matrix:
        for c in range(cols):
            h[c] = h[c] + 1 if row[c] == 1 else 0
        cnt = [0] * cols
        stack = []
        for c in range(cols):
            while stack and h[stack[-1]] >= h[c]:
                stack.pop()
            if stack:
                p = stack[-1]
                cnt[c] = cnt[p] + h[c] * (c - p)
            else:
                cnt[c] = h[c] * (c + 1)
            stack.append(c)
            total += cnt[c]
    return total
